package cc.echomusic.android;
import java.util.*;
public final class QueueContractTest{
    static int checks=0;static void check(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
    public static void main(String[] args){PlaybackQueue<String> queue=new PlaybackQueue<>();queue.replace(Arrays.asList("a","b","c","d"),2);check(queue.current().equals("c"),"initial selected item");long revision=queue.revision();queue.remove(0,revision);check(queue.current().equals("c")&&queue.index()==1,"remove before current preserves track");revision=queue.revision();check(queue.move(1,0,revision)&&queue.current().equals("c")&&queue.index()==0,"move playing item without changing track");revision=queue.revision();check(queue.move(2,0,revision)&&queue.current().equals("c")&&queue.index()==1,"moving another track across current preserves selection");queue.insertNext("next");check(queue.snapshot().get(queue.index()+1).equals("next"),"insert next in live queue");revision=queue.revision();queue.append("last");check(!queue.select(0,revision),"stale dialog cannot select changed queue");check(!queue.move(0,1,revision),"stale dialog cannot reorder changed queue");int size=queue.size();queue.remove(0,revision);check(queue.size()==size,"stale removal is ignored");revision=queue.revision();check(queue.remove(queue.index(),revision)&&queue.current().equals("next"),"removing current selects logical successor");queue.replace(Arrays.asList("a","b"),1);check(queue.remove(1,queue.revision())&&queue.current().equals("a"),"removing last current wraps safely");queue.remove(0,queue.revision());check(queue.current()==null&&queue.index()==-1,"empty queue has no current item");queue.insertNext("first");check(queue.current().equals("first"),"insert into empty queue");queue.clear();check(queue.size()==0&&queue.current()==null,"clear queue");System.out.println("PASS: "+checks+" playback queue contract checks");}
}
